<?php declare(strict_types=1); namespace App\Http\Controllers\Api\V1\Admin; use App\Http\Controllers\Api\V1\Admin\Concerns\AuthorizesAdminAccess; use App\Http\Controllers\Controller; use App\Http\Requests\Admin\SyncUserRolesRequest; use App\Http\Requests\Admin\UserRequest; use App\Http\Resources\Admin\AdminUserResource; use App\Models\User; use App\Services\Admin\UserService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; final class AdminUserController extends Controller { use AuthorizesAdminAccess; public function __construct(private UserService $service){} public function index(Request $r): JsonResponse { $this->authorizeAdmin('user.manage'); $this->authorize('viewAny',User::class); return AdminUserResource::collection($this->service->paginate($r->only(['q','active','department_id']),(int)$r->integer('per_page',15)))->response(); } public function store(UserRequest $r): JsonResponse { $this->authorizeAdmin('user.manage'); $this->authorize('create',User::class); return response()->json(['data'=>AdminUserResource::make($this->service->store($r->validated()))],201);} public function update(UserRequest $r,int $id): JsonResponse { $u=$this->service->findOrFail($id); $this->authorizeAdmin('user.manage'); $this->authorize('update',$u); return response()->json(['data'=>AdminUserResource::make($this->service->update($u,$r->validated(),$r->user()))]); } public function syncRoles(SyncUserRolesRequest $r,int $id): JsonResponse { $u=$this->service->findOrFail($id); $this->authorizeAdmin('role.assign'); $this->authorize('assignRoles',$u); return response()->json(['data'=>AdminUserResource::make($this->service->syncRoles($u,$r->validated('roles'),$r->user()))]); } public function effectivePermissions(int $id): JsonResponse { $u=$this->service->findOrFail($id); $this->authorizeAdmin('role.manage'); $this->authorize('viewEffectivePermissions',$u); return response()->json(['data'=>$this->service->effectivePermissions($u)]); }}